package com.universe.community.controller; import com.universe.community.dto.request.*; import com.universe.community.dto.response.*; import com.universe.community.service.CommunityPostService; import com.universe.global.common.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/v1/community/posts") @RequiredArgsConstructor public class CommunityPostController {private final CommunityPostService service; @GetMapping public ApiResponse<PageResponse<CommunityPostListResponse>> list(@RequestParam(required=false)String category,@RequestParam(required=false)String keyword,@RequestParam(required=false)String hashtag,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size,@RequestParam(defaultValue="latest")String sort){return ApiResponse.success(service.list(category,keyword,hashtag,sort,page,size));} @PostMapping public ApiResponse<CommunityPostResponse> create(@Valid @RequestBody PostCreateRequest r){return ApiResponse.success(service.create(r));} @GetMapping("/{postId}") public ApiResponse<CommunityPostDetailResponse> detail(@PathVariable Long postId){return ApiResponse.success(service.detail(postId));} @PatchMapping("/{postId}") public ApiResponse<CommunityPostResponse> update(@PathVariable Long postId,@Valid @RequestBody PostUpdateRequest r){return ApiResponse.success(service.update(postId,r));} @DeleteMapping("/{postId}") public ApiResponse<Void> delete(@PathVariable Long postId){service.delete(postId);return ApiResponse.success();}}
